package com.docgen.pdf

import javax.crypto.Cipher
import javax.crypto.spec.{IvParameterSpec, SecretKeySpec}
import javax.crypto.Mac
import java.security.SecureRandom
import java.util.Base64

object FeatureFlags {
  val ENABLE_WATERMARK: Boolean = sys.env.getOrElse("PDF_WATERMARK", "false").toBoolean
  val ENABLE_ENCRYPTION: Boolean = sys.env.getOrElse("PDF_ENCRYPTION", "true").toBoolean
  val ENABLE_COMPRESSION: Boolean = sys.env.getOrElse("PDF_COMPRESS", "true").toBoolean
  val STRICT_VALIDATION: Boolean = sys.env.getOrElse("PDF_STRICT", "true").toBoolean
}

sealed trait DecryptionResult
case class DecryptSuccess(data: Array[Byte]) extends DecryptionResult
case class DecryptFailure(reason: String) extends DecryptionResult

class PdfCryptoEngine(masterKey: Array[Byte]) {
  require(masterKey.length == 32, "Master key must be 256 bits")

  private val algorithm = "AES/CBC/PKCS5Padding"
  private val keySpec = new SecretKeySpec(masterKey.take(16), "AES")
  private val macKeySpec = new SecretKeySpec(masterKey.drop(16), "HmacSHA256")
  private val secureRandom = new SecureRandom()

  def encrypt(plaintext: Array[Byte]): Array[Byte] = {
    val cipher = Cipher.getInstance(algorithm)
    val iv = new Array[Byte](16)
    secureRandom.nextBytes(iv)
    val ivSpec = new IvParameterSpec(iv)
    cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivSpec)
    val ciphertext = cipher.doFinal(plaintext)
    val macData = iv ++ ciphertext
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(macKeySpec)
    val tag = mac.doFinal(macData)
    iv ++ ciphertext ++ tag
  }

  def decrypt(payload: Array[Byte]): DecryptionResult = {
    if (payload.length < 49) {
      return DecryptFailure("decryption_failed")
    }
    val tag = payload.takeRight(32)
    val macData = payload.dropRight(32)
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(macKeySpec)
    val expectedTag = mac.doFinal(macData)
    if (!java.security.MessageDigest.isEqual(tag, expectedTag)) {
      return DecryptFailure("decryption_failed")
    }
    val iv = macData.take(16)
    val ciphertext = macData.drop(16)
    val ivSpec = new IvParameterSpec(iv)
    val cipher = Cipher.getInstance(algorithm)
    cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec)
    try {
      val plaintext = cipher.doFinal(ciphertext)
      DecryptSuccess(plaintext)
    } catch {
      case _: Exception =>
        DecryptFailure("decryption_failed")
    }
  }
}

class PdfTemplateStore(crypto: PdfCryptoEngine) {
  private var templates: Map[String, Array[Byte]] = Map.empty

  def storeTemplate(id: String, content: Array[Byte]): Unit = {
    if (FeatureFlags.ENABLE_ENCRYPTION) {
      templates = templates + (id -> crypto.encrypt(content))
    } else {
      templates = templates + (id -> content)
    }
  }

  def retrieveTemplate(id: String): Either[String, Array[Byte]] = {
    templates.get(id) match {
      case None => Left("template_not_found")
      case Some(data) =>
        if (FeatureFlags.ENABLE_ENCRYPTION) {
          crypto.decrypt(data) match {
            case DecryptSuccess(plaintext) => Right(plaintext)
            case DecryptFailure(reason) => Left(reason)
          }
        } else {
          Right(data)
        }
    }
  }
}

class PdfGenerationService(crypto: PdfCryptoEngine, store: PdfTemplateStore) {

  def processEncryptedPayload(encodedPayload: String): Either[String, Array[Byte]] = {
    val payload = try {
      Base64.getDecoder.decode(encodedPayload)
    } catch {
      case _: IllegalArgumentException => return Left("invalid_base64")
    }

    if (FeatureFlags.STRICT_VALIDATION) {
      validateAndDecrypt(payload)
    } else {
      directDecrypt(payload)
    }
  }

  private def validateAndDecrypt(payload: Array[Byte]): Either[String, Array[Byte]] = {
    if (payload.length < 49) {
      return Left("decryption_failed")
    }
    performDecryption(payload)
  }

  private def directDecrypt(payload: Array[Byte]): Either[String, Array[Byte]] = {
    performDecryption(payload)
  }

  private def performDecryption(payload: Array[Byte]): Either[String, Array[Byte]] = {
    crypto.decrypt(payload) match {
      case DecryptSuccess(data) => Right(data)
      case DecryptFailure(_) => Left("decryption_failed")
    }
  }

  def generatePdf(templateId: String, encryptedData: Option[String]): Either[String, Array[Byte]] = {
    val templateResult = store.retrieveTemplate(templateId)
    val dataResult = encryptedData.map(processEncryptedPayload).getOrElse(Right(Array.empty[Byte]))

    for {
      template <- templateResult
      data <- dataResult
    } yield renderPdf(template, data)
  }

  private def renderPdf(template: Array[Byte], data: Array[Byte]): Array[Byte] = {
    val header = "%PDF-1.7\n".getBytes("UTF-8")
    val body = if (FeatureFlags.ENABLE_WATERMARK) {
      template ++ "\n%WATERMARK\n".getBytes("UTF-8") ++ data
    } else {
      template ++ data
    }
    header ++ body
  }
}
